function tree(a                )        { if(!a.length||a[0]===null)return null; const root  ={v:a[0],l:null,r:null};const q    =[root];let j=1;for(let i=0;i<q.length&&j<a.length;i++){for(const side of ['l','r']         ){const v=a[j++];if(v!==null&&v!==undefined){const n  ={v,l:null,r:null};q[i][side]=n;q.push(n);}}}return root;}
export function inorderSuccessor(values                 , target        )              {
let n=tree(values),best            =null;while(n){if(n.v>target){best=n.v;n=n.l;}else n=n.r;}return best;
}

referenceSolutions.typescript:
type N = {v:number,l:N|null,r:N|null};
function tree(a:(number|null)[]):N|null { if(!a.length||a[0]===null)return null; const root:N={v:a[0],l:null,r:null};const q:N[]=[root];let j=1;for(let i=0;i<q.length&&j<a.length;i++){for(const side of ['l','r'] as const){const v=a[j++];if(v!==null&&v!==undefined){const n:N={v,l:null,r:null};q[i][side]=n;q.push(n);}}}return root;}
export function inorderSuccessor(values: (number|null)[], target: number): number|null {
let n=tree(values),best:number|null=null;while(n){if(n.v>target){best=n.v;n=n.l;}else n=n.r;}return best;
}
